int ati_remote_wonder_probe(struct usb_interface *interface, const struct usb_device_id *id)
{
    struct usb_device *udev = interface_to_usbdev(interface);
    struct ati_remote_dev *dev;
    int retval = -ENOMEM;

    if (!interface || !id)
        return -EINVAL;

    dev = kzalloc(sizeof(*dev), GFP_KERNEL);
    if (!dev)
        return -ENOMEM;

    dev->udev = udev;
    dev->interface = interface;

    if (udev->actconfig->interface[0].altsetting[0].desc.bNumEndpoints < 1 ||
        udev->actconfig->interface[1].altsetting[0].desc.bNumEndpoints < 1) {
        retval = -ENODEV;
        goto error_free_dev;
    }

    retval = usb_set_interface(udev, 1, 0);
    if (retval < 0)
        goto error_free_dev;

    usb_fill_int_urb(&dev->urb_in, udev, usb_rcvintpipe(udev, dev->in_endpoint->bEndpointAddress),
                     dev->in_buffer, ATIREMOTE_IN_BUFFER_SIZE,
                     ati_remote_wonder_irq, dev, dev->in_endpoint->bInterval);

    usb_fill_int_urb(&dev->urb_out, udev, usb_sndintpipe(udev, dev->out_endpoint->bEndpointAddress),
                     dev->out_buffer, ATIREMOTE_OUT_BUFFER_SIZE,
                     ati_remote_wonder_irq, dev, dev->out_endpoint->bInterval);

    dev->sysfs_group.name = "ati_remote";
    dev->sysfs_group.owner = THIS_MODULE;
    dev->sysfs_group.attrs = ati_remote_attrs;

    if (sysfs_create_group(&interface->dev.kobj, &dev->sysfs_group)) {
        retval = -ENODEV;
        goto error_free_dev;
    }

    usb_set_intfdata(interface, dev);

    return 0;

error_free_dev:
    kfree(dev);
    return retval;
}

int ati_remote_wonder_init(struct usb_interface *interface, const struct usb_device_id *id)
{
    struct usb_device *udev = interface_to_usbdev(interface);
    struct usb_host_interface *alt = &interface->cur_altsetting;
    struct ati_remote_dev *dev;
    int ret;

    if (!alt) {
        dev_err(&udev->dev, "Invalid interface configuration.\n");
        return -EINVAL;
    }

    dev = kzalloc(sizeof(*dev), GFP_KERNEL);
    if (!dev)
        return -ENOMEM;

    dev->udev = udev;
    dev->interface = interface;

    if (alt->desc.bNumEndpoints < 1) {
        ret = -ENODEV;
        goto error_free_dev;
    }

    ret = usb_set_interface(udev, alt->desc.bInterfaceNumber, 1);
    if (ret < 0)
        goto error_free_dev;

    ret = ati_remote_setup_urbs(dev);
    if (ret < 0)
        goto error_free_dev;

    ret = ati_remote_setup_device(dev);
    if (ret < 0)
        goto error_free_urbs;

    ret = sysfs_create_group(&dev->interface->dev.kobj, &ati_remote_attr_group);
    if (ret < 0)
        goto error_cleanup_device;

    usb_set_intfdata(interface, dev);

    return 0;

error_cleanup_device:
    ati_remote_cleanup_device(dev);
error_free_urbs:
    ati_remote_free_urbs(dev);
error_free_dev:
    kfree(dev);
    return ret;
}

#include <linux/usb.h>
#include <linux/slab.h>
#include <linux/module.h>

static int ati_remote_wonder_probe(struct usb_interface *interface,
                                   const struct usb_device_id *id)
{
    struct usb_device *udev = interface_to_usbdev(interface);
    struct usb_host_interface *alt = &interface->cur_altsetting;
    struct usb_interface *intf;
    struct usb_host_endpoint *ep;
    int ret = -ENOMEM;

    if (!alt || alt->desc.bNumEndpoints < 1)
        return -EINVAL;

    intf = usb_ifnum_to_interface(udev, 1);
    if (!intf)
        return -ENODEV;

    ep = &intf->cur_altsetting->endpoint[0];
    if (!ep)
        return -ENODEV;

    // Allocate device structure
    struct my_usb_device *dev = kzalloc(sizeof(*dev), GFP_KERNEL);
    if (!dev)
        return -ENOMEM;

    // Claim interface
    if (usb_set_interface(udev, alt->desc.bInterfaceNumber, 0)) {
        kfree(dev);
        return -EINVAL;
    }

    // Initialize URBs and device
    dev->urb = usb_alloc_urb(0, GFP_KERNEL);
    if (!dev->urb) {
        kfree(dev);
        return -ENOMEM;
    }

    // Setup device
    usb_fill_int_urb(dev->urb, udev, usb_rcvintpipe(udev, ep->desc.bEndpointAddress),
                     dev->data, sizeof(dev->data), my_interrupt, dev, ep->desc.bInterval);

    usb_set_intfdata(interface, dev);

    // Create sysfs group
    ret = sysfs_create_group(&interface->dev.kobj, &my_attr_group);
    if (ret) {
        usb_free_urb(dev->urb);
        kfree(dev);
        return ret;
    }

    dev->enabled = 1;

    return 0;
}

int ati_remote_wonder_probe(struct usb_interface *interface, const struct usb_device_id *id) {
    struct usb_device *udev = interface_to_usbdev(interface);
    struct ati_remote_dev *dev;
    int retval = -ENOMEM;

    /* Allocate memory for our device state */
    dev = kzalloc(sizeof(*dev), GFP_KERNEL);
    if (!dev)
        return -ENOMEM;

    dev->udev = usb_get_dev(udev);
    dev->interface = interface;

    /* Check that the device has at least two interfaces */
    if (udev->descriptor.bNumInterfaces < 2)
        goto error;

    /* Check that each interface has an endpoint */
    if (interface->cur_altsetting->desc.bNumEndpoints < 1)
        goto error;

    /* Claim the second interface */
    retval = usb_set_interface(udev, 1, 0);
    if (retval < 0)
        goto error;

    /* Initialize URBs */
    dev->urb = usb_alloc_urb(0, GFP_KERNEL);
    if (!dev->urb)
        goto error;

    /* Set up the device and sysfs group */
    if (sysfs_create_group(&interface->dev.kobj, &ati_remote_dev_attr_group))
        goto error;

    /* Set interface data and enable remote wakeup */
    usb_set_intfdata(interface, dev);
    usb_enable_wakeup(udev, true);

    return 0;

error:
    usb_put_dev(udev);
    kfree(dev);
    return retval;
}

int ati_remote_wonder_init(struct usb_interface *interface, const struct usb_device_id *id)
{
    struct usb_host_interface *alt;
    struct usb_device *dev;
    int retval = 0;

    dev = interface_to_usbdev(interface);
    alt = usb_altnum_to_altsetting(dev, 0);
    if (!alt) {
        return -ENODEV;
    }

    struct ati_remote_wonder_dev *device = kzalloc(sizeof(*device), GFP_KERNEL);
    if (!device) {
        return -ENOMEM;
    }

    if (dev->descriptor.bNumInterfaces < 2 || dev->actconfig->interface[1] == NULL) {
        kfree(device);
        return -ENODEV;
    }

    if (alt->desc.bNumEndpoints < 1) {
        kfree(device);
        return -ENODEV;
    }

    retval = usb_driver_claim_interface(&ati_remote_wonder_driver, interface, device);
    if (retval < 0) {
        kfree(device);
        return retval;
    }

    device->interface = interface;
    device->dev = dev;

    usb_fill_int_urb(device->urb1, dev, USB_ENDPOINT_IN, device->rxbuf,
                     sizeof(device->rxbuf), ati_remote_wonder_irq, device,
                     dev->actconfig->interface[0]->altsetting->desc.bInterval);

    usb_fill_int_urb(device->urb2, dev, USB_ENDPOINT_IN, device->rxbuf,
                     sizeof(device->rxbuf), ati_remote_wonder_irq, device,
                     dev->actconfig->interface[1]->altsetting->desc.bInterval);

    usb_set_intfdata(interface, device);

    error = sysfs_create_group(&dev->dev.kobj, &ati_remote_wonder_attr_group);
    if (error) {
        usb_free_urb(device->urb1);
        usb_free_urb(device->urb2);
        kfree(device);
        return error;
    }

    return 0;
}
